import { cn } from "@/components/ui/cn";

/**
 * Parallax – Inhalt verschiebt sich beim Scrollen leicht gegen die Seite.
 * Reines CSS (scroll-driven animation, `animation-timeline: view()`), kein JS,
 * läuft außerhalb des Hauptthreads. Browser ohne Unterstützung und reduzierte
 * Bewegung: steht still. Kein Layout-Einfluss (nur transform).
 *
 * Wann: dekorative Bilder/Illustrationen, Hintergrund-Formen, Bildausschnitte in SplitMedia.
 * Wann NICHT: Text, Formulare, Buttons, Inhalte mit sticky/fixed, das Hero-LCP-Bild.
 * Bild in einen Rahmen mit overflow-hidden legen und leicht vergrößern (z. B. `scale-110`),
 * damit beim Verschieben keine Kanten sichtbar werden.
 *
 * @param {object} p
 * @param {string|React.ElementType} [p.as="div"]
 * @param {number} [p.staerke=32]  Maximaler Versatz in px (nach oben und unten). Empfohlen 16–48.
 *
 * @example
 * <div className="overflow-hidden rounded-3xl">
 *   <Parallax staerke={24}><Image className="scale-110" … /></Parallax>
 * </div>
 */
export default function Parallax({ as: Tag = "div", staerke = 32, className, style, children, ...rest }) {
  return (
    <Tag className={cn("ov-parallax", className)} style={{ "--ov-parallax": `${staerke}px`, ...style }} {...rest}>
      {children}
    </Tag>
  );
}
import { cn } from "@/components/ui/cn";

/**
 * KippKarte – Karte neigt sich dezent (max. 3°) zum Mauszeiger.
 * Logik im globalen <MotionInteraktion/>; nur Maus/Trackpad, nicht bei
 * reduzierter Bewegung. Kombinierbar mit `ov-lift` / `ov-card-hover`
 * (das Anheben bleibt erhalten).
 *
 * Wann: einzelne Vorzeige-Objekte (Produkt-/App-Mockup, Zertifikat, große Kennzahl-Kachel).
 * Wann NICHT: Raster mit vielen Karten, Karten mit Formularen oder viel Text, Elemente
 * mit eigenem `transform`.
 *
 * @param {object} p
 * @param {string|React.ElementType} [p.as="div"]
 * @param {number} [p.grad=3]  Maximaler Kippwinkel in Grad (1–5).
 *
 * @example
 * <KippKarte className="ov-flaeche-erhaben ov-lift p-6">…</KippKarte>
 */
export default function KippKarte({ as: Tag = "div", grad, className, children, ...rest }) {
  return (
    <Tag className={cn("ov-kipp", className)} data-kipp={grad ? String(grad) : undefined} {...rest}>
      {children}
    </Tag>
  );
}
import { cn } from "@/components/ui/cn";

/**
 * PfadZeichnen – SVG-Linien zeichnen sich, sobald der Block ins Bild scrollt.
 * Server-Komponente; ausgelöst vom globalen RevealObserver.
 *
 * Gezeichnet werden alle <path|line|polyline|polygon|circle|ellipse|rect> mit
 * `pathLength="1"` im Inneren (bestehende `.ov-linie`-Pfade funktionieren ebenso).
 * Für gestaffelte Linien `style={{ "--i": n }}` am Pfad setzen.
 * Ohne JS / reduzierte Bewegung: Linien stehen sofort vollständig.
 *
 * Wann: Verbindungslinien, Energiefluss-Skizzen, Diagramm-Kurven, Icon-Konturen.
 * Wann NICHT: gestrichelte Linien (stroke-dasharray wird überschrieben), Text-Pfade,
 * flächige Illustrationen.
 *
 * @param {object} p
 * @param {string|React.ElementType} [p.as="div"]
 * @param {number} [p.dauer=1100]      Zeichendauer in ms.
 * @param {number} [p.verzoegerung=0]  Startversatz in ms.
 * @param {number} [p.schritt=0]       Versatz je `--i` in ms.
 * @param {boolean} [p.sofort=false]   Sofort beim Laden zeichnen (Hero), ohne Scroll-Auslöser.
 *
 * @example
 * <PfadZeichnen schritt={120}>
 *   <svg viewBox="0 0 400 120" aria-hidden="true">
 *     <path pathLength="1" d="M0 100 C 120 10, 280 10, 400 100" stroke="currentColor" fill="none" />
 *   </svg>
 * </PfadZeichnen>
 */
export default function PfadZeichnen({ as: Tag = "div", dauer, verzoegerung = 0, schritt, sofort = false, className, style, children, ...rest }) {
  const stil = {
    ...(dauer ? { "--ov-pfad-dauer": `${dauer}ms` } : {}),
    ...(verzoegerung ? { "--ov-delay": `${verzoegerung}ms` } : {}),
    ...(schritt ? { "--ov-pfad-schritt": `${schritt}ms` } : {}),
    ...style,
  };
  return (
    <Tag
      suppressHydrationWarning={!sofort || undefined}
      data-dir={sofort ? undefined : "ohne"}
      className={cn("ov-pfad", sofort ? "ov-sofort" : "ov-reveal", className)}
      style={stil}
      {...rest}
    >
      {children}
    </Tag>
  );
